# Numeric, statistical, logical, scientific, and clinical validation suite for advancedraincloud
# Generated by /validate-function advancedraincloud depth=exhaustive on 2026-11-11.
# All 12 validation defects (VAL-advancedraincloud-01 .. VAL-advancedraincloud-12) have been
# resolved and verified without skip() guards under /check-function advancedraincloud --profile release.

quiet_arc <- function(expr) suppressWarnings(suppressMessages(force(expr)))

clean_arc_html <- function(html) {
  if (is.null(html) || length(html) == 0L || is.na(html)) return("")
  s <- gsub("</?[a-zA-Z][^>]*>", " ", as.character(html))
  s <- gsub("&lt;", "<", s, fixed = TRUE)
  s <- gsub("&gt;", ">", s, fixed = TRUE)
  s <- gsub("&amp;", "&", s, fixed = TRUE)
  s <- gsub("&quot;", "\"", s, fixed = TRUE)
  s <- gsub("&#39;", "'", s, fixed = TRUE)
  trimws(gsub("[[:space:]]+", " ", s))
}

extract_arc_td_rows <- function(html) {
  if (is.null(html) || !nzchar(html)) return(list())
  trs <- regmatches(html, gregexpr("<tr[^>]*>.*?</tr>", html, perl = TRUE))[[1]]
  out <- list()
  for (tr in trs) {
    if (grepl("<th", tr, fixed = TRUE)) next
    tds <- regmatches(tr, gregexpr("<td[^>]*>.*?</td>", tr, perl = TRUE))[[1]]
    if (length(tds) > 0L) {
      out[[length(out) + 1L]] <- vapply(tds, clean_arc_html, character(1), USE.NAMES = FALSE)
    }
  }
  out
}

parse_arc_stats <- function(html) {
  tbl1 <- regmatches(html, regexpr("<table[^>]*>.*?</table>", html, perl = TRUE))
  rows <- extract_arc_td_rows(tbl1)
  mat <- do.call(rbind, rows)
  rng <- strsplit(mat[, 6], " - ", fixed = TRUE)
  data.frame(
    Group = mat[, 1],
    N = as.integer(mat[, 2]),
    Mean = as.numeric(mat[, 3]),
    Median = as.numeric(mat[, 4]),
    SD = as.numeric(mat[, 5]),
    Min = vapply(rng, function(z) as.numeric(z[1]), numeric(1)),
    Max = vapply(rng, function(z) as.numeric(z[2]), numeric(1)),
    stringsAsFactors = FALSE
  )
}

parse_arc_kv <- function(html) {
  rows <- extract_arc_td_rows(html)
  res <- list()
  for (r in rows) {
    if (length(r) == 2L) res[[gsub(":$", "", r[1])]] <- r[2]
  }
  res
}

parse_arc_es <- function(html) {
  rows4 <- Filter(function(r) length(r) == 4L, extract_arc_td_rows(html))
  mat <- do.call(rbind, rows4)
  ci_lo <- rep(NA_real_, nrow(mat))
  ci_hi <- rep(NA_real_, nrow(mat))
  for (i in seq_len(nrow(mat))) {
    m <- regmatches(mat[i, 3], regexec("^\\[([^,]+),\\s*([^\\]]+)\\]$", mat[i, 3], perl = TRUE))[[1]]
    if (length(m) == 3L) {
      ci_lo[i] <- as.numeric(m[2])
      ci_hi[i] <- as.numeric(m[3])
    }
  }
  data.frame(
    Comparison = mat[, 1],
    ES = as.numeric(mat[, 2]),
    CI_low = ci_lo,
    CI_high = ci_hi,
    Interpretation = mat[, 4],
    stringsAsFactors = FALSE
  )
}

capture_arc_plot <- function(res) {
  f <- tempfile(fileext = ".pdf")
  grDevices::pdf(f, width = 8, height = 6)
  on.exit({
    try(grDevices::dev.off(), silent = TRUE)
    unlink(f)
  }, add = TRUE)
  quiet_arc(print(res$plot))
  ggplot2::last_plot()
}

test_that("C01-C06: hand-derived summary statistics and missingness counts match exact values", {
  # Oracle: closed-form hand arithmetic on n1=5, n2=5 with 1 NA row and non-ASCII column name.
  df <- data.frame(
    `Gréade sc (ng/mL)` = c(2, 4, 4, 6, 9, 8, 10, 12, 14, 16, NA_real_),
    grp = factor(c(rep("Ctrl", 5), rep("Trt", 5), "Ctrl"), levels = c("Ctrl", "Trt")),
    check.names = FALSE
  )
  res <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df, y_var = "Gréade sc (ng/mL)", x_var = "grp",
    show_statistics = TRUE, show_missing_info = TRUE
  ))
  st <- parse_arc_stats(res$statistics$content)
  expect_identical(st$Group, c("Ctrl", "Trt"))
  expect_identical(st$N, c(5L, 5L))
  expect_equal(st$Mean, c(5, 12), tolerance = 1e-12)
  expect_equal(st$Median, c(4, 12), tolerance = 1e-12)
  expect_equal(st$SD, round(c(sqrt(7), sqrt(10)), 3), tolerance = 1e-12)
  expect_equal(c(st$Min, st$Max), c(2, 8, 9, 16), tolerance = 1e-12)
  expect_match(
    clean_arc_html(res$statistics$content),
    "Original dataset: 11 observations Analysis dataset: 10 observations Excluded \\(incomplete\\): 1 observations \\(9\\.1%\\)"
  )
})

test_that("C07: Wilcoxon rank-sum W and exact conditional permutation p-value match hand combinatorics and coin", {
  # Oracle: hand rank sum R1 = 16 -> W = 1, exact conditional p = 4/choose(10,5) = 1/63; coin::wilcox_test(exact).
  skip_if_not_installed("coin")
  df <- data.frame(
    y = c(2, 4, 4, 6, 9, 8, 10, 12, 14, 16),
    grp = factor(rep(c("Ctrl", "Trt"), each = 5), levels = c("Ctrl", "Trt"))
  )
  res <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df, y_var = "y", x_var = "grp", show_comparisons = TRUE
  ))
  kv <- parse_arc_kv(res$comparisons$content)
  expect_identical(kv[["Test Statistic"]], "W = 1")
  expect_equal(as.numeric(kv[["P-value"]]), round(4 / choose(10, 5), 3), tolerance = 1e-12)
  expect_identical(kv[["Result"]], "Evidence against the null at 0.05")

  df_untied <- data.frame(
    len = c(4.2, 11.5, 7.3, 5.8, 6.4, 10.0, 15.2, 21.5, 17.6, 9.7, 14.5, 23.3),
    supp = factor(rep(c("VC", "OJ"), each = 6), levels = c("VC", "OJ"))
  )
  res2 <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df_untied, y_var = "len", x_var = "supp", show_comparisons = TRUE
  ))
  coin_p <- as.numeric(coin::pvalue(coin::wilcox_test(len ~ supp, data = df_untied, distribution = "exact")))
  expect_equal(as.numeric(parse_arc_kv(res2$comparisons$content)[["P-value"]]), round(coin_p, 3), tolerance = 1e-12)
})

test_that("C08: Kruskal-Wallis H statistic, df, and p-value match hand derivation and coin::kruskal_test", {
  # Oracle: hand H = 7.2, df = 2, p = exp(-3.6) = 0.027 on 3x3 untied ranks; coin::kruskal_test on PlantGrowth.
  skip_if_not_installed("coin")
  df <- data.frame(
    val = 1:9,
    grp = factor(rep(c("G1", "G2", "G3"), each = 3), levels = c("G1", "G2", "G3"))
  )
  res <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df, y_var = "val", x_var = "grp", show_comparisons = TRUE
  ))
  kv <- parse_arc_kv(res$comparisons$content)
  expect_identical(kv[["Test Statistic"]], "\u03c7\u00b2 = 7.2, df = 2")
  expect_equal(as.numeric(kv[["P-value"]]), round(exp(-3.6), 3), tolerance = 1e-12)

  pg <- datasets::PlantGrowth
  res_pg <- quiet_arc(ClinicoPath::advancedraincloud(
    data = pg, y_var = "weight", x_var = "group", show_comparisons = TRUE
  ))
  kw_coin <- coin::kruskal_test(weight ~ group, data = pg, distribution = "asymptotic")
  kv_pg <- parse_arc_kv(res_pg$comparisons$content)
  expect_identical(kv_pg[["Test Statistic"]], paste0("\u03c7\u00b2 = ", round(as.numeric(coin::statistic(kw_coin)), 4), ", df = 2"))
  expect_equal(as.numeric(kv_pg[["P-value"]]), round(as.numeric(coin::pvalue(kw_coin)), 3), tolerance = 1e-12)
})

test_that("C10-C11-C13: Cohen's d, Hedges' g, 95% z-CI, and magnitude bands match closed-form formulas and effsize", {
  # Oracle: Hedges (1981, DOI: 10.3102/10769986006002107) exact formulas and effsize::cohen.d on PlantGrowth & bundled endpoint.
  skip_if_not_installed("effsize")
  df <- data.frame(
    y = c(2, 4, 4, 6, 9, 8, 10, 12, 14, 16),
    grp = factor(rep(c("Ctrl", "Trt"), each = 5), levels = c("Ctrl", "Trt"))
  )
  res_d <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df, y_var = "y", x_var = "grp", show_effect_size = TRUE, effect_size_type = "cohens_d"
  ))
  es_d <- parse_arc_es(res_d$effect_sizes$content)
  d_true <- -7 / sqrt(8.5)
  se_d <- sqrt(117 / 170)
  z95 <- stats::qnorm(0.975)
  expect_equal(es_d$ES[1], round(d_true, 3), tolerance = 1e-12)
  expect_equal(c(es_d$CI_low[1], es_d$CI_high[1]), round(d_true + c(-1, 1) * z95 * se_d, 3), tolerance = 1e-12)
  expect_identical(es_d$Interpretation[1], "Large")

  res_g <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df, y_var = "y", x_var = "grp", show_effect_size = TRUE, effect_size_type = "hedges_g"
  ))
  es_g <- parse_arc_es(res_g$effect_sizes$content)
  J <- 1 - 3 / 31
  expect_equal(es_g$ES[1], round(d_true * J, 3), tolerance = 1e-12)
  expect_equal(c(es_g$CI_low[1], es_g$CI_high[1]), round(d_true * J + c(-1, 1) * z95 * J * se_d, 3), tolerance = 1e-12)

  ep <- ClinicoPath::advancedraincloud_endpoint
  ep_cc <- ep[stats::complete.cases(ep[, c("biomarker_level", "treatment_arm")]), ]
  res_ep <- quiet_arc(ClinicoPath::advancedraincloud(
    data = ep, y_var = "biomarker_level", x_var = "treatment_arm",
    show_effect_size = TRUE, effect_size_type = "hedges_g"
  ))
  g_oracle <- effsize::cohen.d(biomarker_level ~ treatment_arm, data = ep_cc, hedges.correction = TRUE)$estimate
  expect_equal(parse_arc_es(res_ep$effect_sizes$content)$ES[1], round(unname(g_oracle), 3), tolerance = 1e-12)
})

