})

test_that("C17-C18-C20-C21-C23: outlier handling, log(y+0.01) summary stats, plot medians, linear overlays, state redraw, and input guards hold", {
  # Oracle: type-7 quantile hand values, log(y + 0.01) exact means, ggplot_build layer coordinates, and jamovi state-only redraw.
  skip_if_not_installed("ggrain")
  df_out <- data.frame(
    y = c(1, 10, 12, 14, 16, 18, 11, 13, 15, 17, 100),
    g = factor(c(rep("G1", 6), rep("G2", 5)), levels = c("G1", "G2"))
  )
  st_win <- parse_arc_stats(quiet_arc(ClinicoPath::advancedraincloud(
    data = df_out, y_var = "y", x_var = "g", outlier_method = "winsorize", show_statistics = TRUE
  ))$statistics$content)
  expect_equal(c(st_win$N, st_win$Mean, st_win$Min, st_win$Max),
               c(6, 5, round(75.5 / 6, 3), 23, 5.5, 11, 18, 59), tolerance = 1e-12)

  df_lin <- data.frame(
    y = c(10, 12, 14, 16, 20, 25, 30, 35),
    g = factor(rep(c("Control", "Treated"), each = 4), levels = c("Control", "Treated"))
  )
  res_lin <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df_lin, y_var = "y", x_var = "g",
    show_statistics = TRUE, show_comparisons = TRUE,
    show_clinical_cutoff = TRUE, clinical_cutoff = 18,
    show_reference_range = TRUE, reference_range_min = 9, reference_range_max = 15,
    show_mcid = TRUE, mcid_value = 4,
    show_cv_bands = TRUE, cv_band_1 = 10, cv_band_2 = 20
  ))
  b_lin <- ggplot2::ggplot_build(capture_arc_plot(res_lin))
  box_df <- b_lin$data[[2]]
  expect_equal(sort(box_df$middle), c(13, 27.5), tolerance = 1e-12)
  hline_df <- Filter(function(d) "yintercept" %in% names(d), b_lin$data)[[1]]
  expect_equal(hline_df$yintercept[1], 18, tolerance = 1e-12)

  # Internal R6 class is accessed here specifically to simulate jamovi reopen/export where private$.data is NULL (Rule E4).
  opts <- ClinicoPath:::advancedraincloudOptions$new(
    y_var = "y", x_var = "g", show_comparisons = TRUE, p_value_position = "above"
  )
  a1 <- ClinicoPath:::advancedraincloudClass$new(options = opts, data = df_lin)
  a1$run()
  a2 <- ClinicoPath:::advancedraincloudClass$new(options = opts, data = df_lin[0, ])
  a2$.__enclos_env__$private$.data <- NULL
  a2$results$plot$setState(a1$results$plot$state)
  f_pdf <- tempfile(fileext = ".pdf")
  grDevices::pdf(f_pdf, width = 8, height = 6)
  ok_redraw <- quiet_arc(a2$.__enclos_env__$private$.plot(
    a2$results$plot, ggtheme = ggplot2::theme_bw(), theme = NULL
  ))
  grDevices::dev.off()
  unlink(f_pdf)
  expect_true(ok_redraw)

  expect_error(ClinicoPath::advancedraincloud(data = df_lin[0, ], y_var = "y", x_var = "g"), "no complete rows")
  expect_error(ClinicoPath::advancedraincloud(data = df_lin, y_var = "y", x_var = "g", point_alpha = 1.5), "between 0 and 1")
})

