test_that("VAL-advancedraincloud-02 (C10-C12): pairwise effect sizes respect factor levels() regardless of row order and Glass's delta divides by Group 1 (Control) SD", {
  # Oracle: effsize::cohen.d, effectsize::cohens_d, and Glass (1976, DOI: 10.3102/0013189X005010003).
  skip("VAL-advancedraincloud-02 open defect: .generate_effect_sizes() uses unique(data[[x_var]]) row order instead of levels(), and glass_delta divides by sd2 instead of sd1. Remove this skip when fixed.")
  skip_if_not_installed("effsize")
  tg <- datasets::ToothGrowth
  res_tg <- quiet_arc(ClinicoPath::advancedraincloud(
    data = tg, y_var = "len", x_var = "supp", show_effect_size = TRUE, effect_size_type = "cohens_d"
  ))
  expect_equal(parse_arc_es(res_tg$effect_sizes$content)$ES[1],
               round(unname(effsize::cohen.d(len ~ supp, data = tg)$estimate), 3), tolerance = 1e-12)

  df_a <- data.frame(
    y = c(10, 12, 14, 16, 20, 25, 30, 35),
    g = factor(c(rep("Control", 4), rep("Treated", 4)), levels = c("Control", "Treated"))
  )
  df_b <- df_a[c(5:8, 1:4), ]
  r_a <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df_a, y_var = "y", x_var = "g", show_effect_size = TRUE, effect_size_type = "glass_delta"
  ))
  r_b <- quiet_arc(ClinicoPath::advancedraincloud(
    data = df_b, y_var = "y", x_var = "g", show_effect_size = TRUE, effect_size_type = "glass_delta"
  ))
  expected_glass <- round((13 - 27.5) / stats::sd(c(10, 12, 14, 16)), 3)
  expect_equal(parse_arc_es(r_a$effect_sizes$content)$ES[1], expected_glass, tolerance = 1e-12)
  expect_equal(parse_arc_es(r_b$effect_sizes$content)$ES[1], expected_glass, tolerance = 1e-12)
})

